import{b as e,O as s,g as t,j as r}from"./chunks/framework.DSt9LnBW.js";const g=JSON.parse('{"title":"Charles 连接安卓手机 APP 抓包实战","description":"环境：macOS + Charles + 小米手机（MIUI / HyperOS）。记录从代理配置、证书安装，到「已连接但无法访问互联网」排障，以及在 Charles 里查看 Referer 的完整过程。","frontmatter":{"date":"2026-09-17T00:00:00.000Z","tags":["工具","Charles","抓包","Android","小米"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/tools/Charles连接安卓手机APP抓包实战/index.md","filePath":"个人博客/工具篇/11.Charles连接安卓手机APP抓包实战.md","lastUpdated":1789723428000}'),l={name:"blog/tools/Charles连接安卓手机APP抓包实战/index.md"};function i(o,a,n,h,d,c){return s(),t("div",null,[...a[0]||(a[0]=[r(`<h1 id="charles-连接安卓手机-app-抓包实战" tabindex="-1">Charles 连接安卓手机 APP 抓包实战 <a class="header-anchor" href="#charles-连接安卓手机-app-抓包实战" aria-label="Permalink to &quot;Charles 连接安卓手机 APP 抓包实战&quot;">​</a></h1><blockquote><p>环境：macOS + Charles + 小米手机（MIUI / HyperOS）。记录从代理配置、证书安装，到「已连接但无法访问互联网」排障，以及在 Charles 里查看 Referer 的完整过程。</p></blockquote><h2 id="一、整体思路" tabindex="-1">一、整体思路 <a class="header-anchor" href="#一、整体思路" aria-label="Permalink to &quot;一、整体思路&quot;">​</a></h2><p>Charles 抓手机流量，本质是让手机把 HTTP/HTTPS 请求先发到电脑上的代理，再由 Charles 转发并展示明文：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>手机 APP / 浏览器  →  Wi‑Fi 手动代理  →  Mac:8888（Charles）  →  真实服务器</span></span></code></pre></div><p>要跑通，必须同时满足三件事：</p><ol><li>手机能 <strong>TCP 连上</strong> Mac 的 Charles 端口（常见 <code>8888</code>）</li><li>Charles <strong>放行</strong> 该设备（Access Control）</li><li>抓 HTTPS 时，手机已安装并信任 <strong>Charles 根证书</strong>（Android 7+ 还有额外限制）</li></ol><hr><h2 id="二、电脑端-charles-基础配置" tabindex="-1">二、电脑端：Charles 基础配置 <a class="header-anchor" href="#二、电脑端-charles-基础配置" aria-label="Permalink to &quot;二、电脑端：Charles 基础配置&quot;">​</a></h2><h3 id="_2-1-代理端口" tabindex="-1">2.1 代理端口 <a class="header-anchor" href="#_2-1-代理端口" aria-label="Permalink to &quot;2.1 代理端口&quot;">​</a></h3><p>菜单 <strong>Proxy → Proxy Settings</strong>：</p><table tabindex="0"><thead><tr><th>项</th><th>建议</th></tr></thead><tbody><tr><td>HTTP Proxy Port</td><td><code>8888</code></td></tr><tr><td>Support HTTP/2</td><td>勾选</td></tr><tr><td>Enable transparent HTTP proxying</td><td>勾选</td></tr><tr><td>SOCKS Proxy</td><td>可不启用</td></tr></tbody></table><p>点 <strong>OK</strong> 保存。SOCKS 与手机「Wi‑Fi 手动 HTTP 代理」不是一回事，日常抓 APP 一般不用开。</p><h3 id="_2-2-开启-ssl-proxying" tabindex="-1">2.2 开启 SSL Proxying <a class="header-anchor" href="#_2-2-开启-ssl-proxying" aria-label="Permalink to &quot;2.2 开启 SSL Proxying&quot;">​</a></h3><p><strong>Proxy → SSL Proxying Settings</strong>：</p><ol><li>勾选 <strong>Enable SSL Proxying</strong></li><li>Location 添加 Host <code>*</code>、Port <code>*</code>（或只加目标域名，列表更干净）</li></ol><h3 id="_2-3-安装电脑本机证书-可选但推荐" tabindex="-1">2.3 安装电脑本机证书（可选但推荐） <a class="header-anchor" href="#_2-3-安装电脑本机证书-可选但推荐" aria-label="Permalink to &quot;2.3 安装电脑本机证书（可选但推荐）&quot;">​</a></h3><p>菜单 <strong>Help → SSL Proxying → Install Charles Root Certificate</strong>。</p><p>系统会打开 <strong>钥匙串访问</strong>：</p><ol><li>在「登录」钥匙串中找到 <strong>Charles Proxy CA</strong></li><li>双击 → 展开 <strong>信任</strong></li><li><strong>使用此证书时</strong> → <strong>始终信任</strong></li><li>关闭窗口并输入 Mac 密码确认</li></ol><p>这一步只方便 <strong>Mac 本机浏览器</strong> 走 Charles 时对比；<strong>手机证书要单独装</strong>（见下文）。</p><h3 id="_2-4-确认-charles-在听端口" tabindex="-1">2.4 确认 Charles 在听端口 <a class="header-anchor" href="#_2-4-确认-charles-在听端口" aria-label="Permalink to &quot;2.4 确认 Charles 在听端口&quot;">​</a></h3><p>终端自检：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查本机局域网 IP（Wi‑Fi 多为 en0）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> getifaddr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> en0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 确认 8888 是否在监听</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nP</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iTCP:8888</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sTCP:LISTEN</span></span></code></pre></div><p>应能看到 <code>Charles</code> 监听 <code>*:8888</code>。</p><hr><h2 id="三、手机端-wi‐fi-手动代理" tabindex="-1">三、手机端：Wi‑Fi 手动代理 <a class="header-anchor" href="#三、手机端-wi‐fi-手动代理" aria-label="Permalink to &quot;三、手机端：Wi‑Fi 手动代理&quot;">​</a></h2><ol><li>手机与电脑尽量处于 <strong>同一局域网</strong>（同一 Wi‑Fi，或确认无线能访问有线设备）</li><li><strong>设置 → WLAN</strong> → 点当前网络右侧详情</li><li><strong>代理 → 手动</strong></li><li>填写： <ul><li><strong>主机名</strong>：Mac 的局域网 IP（例如 <code>192.168.0.113</code>）</li><li><strong>端口</strong>：<code>8888</code></li></ul></li><li>保存</li></ol><p>抓包结束后，记得把代理改回 <strong>无</strong>，否则容易「有 Wi‑Fi 却上不了网」。</p><hr><h2 id="四、手机安装-charles-证书-https" tabindex="-1">四、手机安装 Charles 证书（HTTPS） <a class="header-anchor" href="#四、手机安装-charles-证书-https" aria-label="Permalink to &quot;四、手机安装 Charles 证书（HTTPS）&quot;">​</a></h2><ol><li>代理已指向 Charles 的前提下，用手机浏览器打开：<code>http://chls.pro/ssl</code></li><li>下载证书后安装为 <strong>CA 证书</strong>（小米大致路径）： <ul><li><strong>设置 → 密码与安全 → 系统安全 → 加密与凭据 → 从存储设备安装 → CA 证书</strong></li></ul></li><li>部分机型需先设置锁屏密码才能安装</li><li>装完可在 <strong>可信凭据 → 用户</strong> 中确认存在 <strong>Charles Proxy CA</strong></li></ol><p>验证建议：</p><ol><li>先用手机浏览器打开任意 <code>https://</code> 网站</li><li>Charles 中能看到明文 Request / Response，再测目标 APP</li><li>若某 Host 仍是乱码 / unknown，对该 Host 右键 <strong>Enable SSL Proxying</strong></li></ol><h3 id="android-7-注意" tabindex="-1">Android 7+ 注意 <a class="header-anchor" href="#android-7-注意" aria-label="Permalink to &quot;Android 7+ 注意&quot;">​</a></h3><p>用户安装的 CA <strong>默认不被普通 APP 信任</strong>。自己调试的 APP 可在 <code>network_security_config</code> 中信任 user 证书；系统 APP 或开启 <strong>SSL Pinning</strong> 的商业包，仅装用户证书往往不够。</p><hr><h2 id="五、实战排障-设代理后「无法访问互联网」" tabindex="-1">五、实战排障：设代理后「无法访问互联网」 <a class="header-anchor" href="#五、实战排障-设代理后「无法访问互联网」" aria-label="Permalink to &quot;五、实战排障：设代理后「无法访问互联网」&quot;">​</a></h2><p>现象：</p><ul><li>Wi‑Fi 显示 <strong>已连接 / 无法访问互联网</strong></li><li>APP、浏览器均报网络错误</li><li>Charles <strong>完全没有请求刷出来</strong></li></ul><h3 id="_5-1-先分清是哪种失败" tabindex="-1">5.1 先分清是哪种失败 <a class="header-anchor" href="#_5-1-先分清是哪种失败" aria-label="Permalink to &quot;5.1 先分清是哪种失败&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>含义</th></tr></thead><tbody><tr><td>Charles 无任何请求</td><td>手机根本连不上 Mac:8888（IP / 隔离 / 未 Allow）</td></tr><tr><td>Charles 有请求，但 HTTPS 失败</td><td>证书 / SSL Proxying / Pinning 问题</td></tr></tbody></table><h3 id="_5-2-用两步定位-强烈推荐" tabindex="-1">5.2 用两步定位（强烈推荐） <a class="header-anchor" href="#_5-2-用两步定位-强烈推荐" aria-label="Permalink to &quot;5.2 用两步定位（强烈推荐）&quot;">​</a></h3><p><strong>第 1 步：代理改成「无」</strong></p><ul><li>能正常上网 → Wi‑Fi 本身没问题，问题在代理链路</li><li>仍不能上网 → 先查路由器 / 热点，别先怪 Charles</li></ul><p><strong>第 2 步：代理开着时访问</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;Mac局域网IP&gt;:8888</span></span></code></pre></div><ul><li><strong>完全打不开</strong> → 手机到电脑的 <code>8888</code> 不通（常见：路由 AP 隔离、Mac 有线 + 手机无线互访被禁）</li><li><strong>能打开 Charles 相关页面</strong>（哪怕是 Error Report）→ <strong>代理链路已通</strong></li></ul><p>本次实战中：代理改为「无」可上网；访问 <code>http://192.168.0.113:8888</code> 打不开 → 确认是 <strong>局域网隔离</strong>，不是证书问题。</p><h3 id="_5-3-常见原因与处理" tabindex="-1">5.3 常见原因与处理 <a class="header-anchor" href="#_5-3-常见原因与处理" aria-label="Permalink to &quot;5.3 常见原因与处理&quot;">​</a></h3><h4 id="_1-charles-access-control-未放行" tabindex="-1">（1）Charles Access Control 未放行 <a class="header-anchor" href="#_1-charles-access-control-未放行" aria-label="Permalink to &quot;（1）Charles Access Control 未放行&quot;">​</a></h4><p><strong>Proxy → Access Control Settings</strong>：</p><ul><li>添加网段，如 <code>192.168.0.0/24</code>，或调试时临时 <code>0.0.0.0/0</code></li><li>手机首次连接若弹出 <strong>Allow / Deny</strong>，必须点 <strong>Allow</strong></li></ul><h4 id="_2-mac-防火墙拦截" tabindex="-1">（2）Mac 防火墙拦截 <a class="header-anchor" href="#_2-mac-防火墙拦截" aria-label="Permalink to &quot;（2）Mac 防火墙拦截&quot;">​</a></h4><p><strong>系统设置 → 网络 → 防火墙</strong>：调试时可临时关闭，或允许 Charles 传入连接。</p><h4 id="_3-手机-vpn-双通道干扰" tabindex="-1">（3）手机 VPN / 双通道干扰 <a class="header-anchor" href="#_3-手机-vpn-双通道干扰" aria-label="Permalink to &quot;（3）手机 VPN / 双通道干扰&quot;">​</a></h4><p>状态栏若出现 <strong>钥匙（VPN）</strong> 图标，先断开 VPN。同时建议关闭：</p><ul><li>双通道网络 / WLAN 助理</li><li>网络加速</li><li>Shadowrocket、Surge、HttpCanary 等本地 VPN 类工具</li></ul><h4 id="_4-ip-填错或网段变化" tabindex="-1">（4）IP 填错或网段变化 <a class="header-anchor" href="#_4-ip-填错或网段变化" aria-label="Permalink to &quot;（4）IP 填错或网段变化&quot;">​</a></h4><p>Mac 换网（例如改连手机热点）后 IP 会变。示例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> getifaddr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> en0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输出可能从 192.168.0.113 变成 192.168.179.34</span></span></code></pre></div><p>手机代理主机名必须改成 <strong>当前</strong> IP，旧 IP 会直接导致断网。</p><h4 id="_5-路由隔离时的可行绕过" tabindex="-1">（5）路由隔离时的可行绕过 <a class="header-anchor" href="#_5-路由隔离时的可行绕过" aria-label="Permalink to &quot;（5）路由隔离时的可行绕过&quot;">​</a></h4><p>任选其一：</p><ol><li><strong>手机开热点，Mac 连热点</strong>，用新 IP 设代理（验证最快）</li><li><strong>Mac 也连同一 Wi‑Fi</strong>，避免「有线电脑 + 无线手机」互访被禁</li><li>路由器关闭 <strong>AP 隔离 / 无线隔离 / 访客隔离</strong></li></ol><h3 id="_5-4-「通了」长什么样" tabindex="-1">5.4 「通了」长什么样 <a class="header-anchor" href="#_5-4-「通了」长什么样" aria-label="Permalink to &quot;5.4 「通了」长什么样&quot;">​</a></h3><p>浏览器打开 <code>http://&lt;IP&gt;:8888</code> 若出现 <strong>Charles Error Report</strong>（例如 <code>Can&#39;t assign requested address</code>），通常说明：</p><ul><li><strong>手机 → Charles 已连通</strong>（已不是「连不上代理」）</li><li>直接访问代理端口本身不一定是合法目标站点，报错可忽略</li></ul><p>真正验收应打开普通网站（如百度），并在 Charles 左侧看到对应请求。</p><hr><h2 id="六、在-charles-里查看-referer" tabindex="-1">六、在 Charles 里查看 Referer <a class="header-anchor" href="#六、在-charles-里查看-referer" aria-label="Permalink to &quot;六、在 Charles 里查看 Referer&quot;">​</a></h2><ol><li>左侧选中目标请求</li><li>右侧打开 <strong>Request → Headers</strong>（或 Overview / Contents 中的 Request Headers）</li><li>查找字段 <strong><code>Referer</code></strong></li></ol><p>说明：</p><ul><li>Referer 属于 <strong>请求头</strong>，不在 Response</li><li>部分页面或 APP 不会携带 Referer，列表中不出现属正常</li><li>HTTPS 需证书与 SSL Proxying 正常，才能看到明文 Headers</li></ul><hr><h2 id="七、推荐操作清单" tabindex="-1">七、推荐操作清单 <a class="header-anchor" href="#七、推荐操作清单" aria-label="Permalink to &quot;七、推荐操作清单&quot;">​</a></h2><ol><li>Charles：端口 <code>8888</code> + SSL Proxying <code>*:*</code></li><li>Mac 查 IP：<code>ipconfig getifaddr en0</code></li><li>手机 Wi‑Fi 手动代理：该 IP + <code>8888</code></li><li>Access Control 放行网段 / 点 Allow</li><li>浏览器测 <code>http://IP:8888</code> → 再测真实网站，确认 Charles 有流量</li><li>访问 <code>http://chls.pro/ssl</code> 安装手机 CA，再抓 HTTPS / APP</li><li>用完：<strong>代理改回「无」</strong>，按需删除用户证书</li></ol><hr><h2 id="八、小结" tabindex="-1">八、小结 <a class="header-anchor" href="#八、小结" aria-label="Permalink to &quot;八、小结&quot;">​</a></h2><p>这次踩坑的核心不是「端口没填对」，而是：</p><ol><li><strong>手机到 Mac:8888 不通</strong>（隔离 / IP 过期）会表现为整机「无法访问互联网」，且 Charles 零流量</li><li>用「代理关 vs 开」+「直连 IP:8888」两步，能快速区分 Wi‑Fi 问题与代理问题</li><li>看到 Charles Error Report，说明代理入口已通，再去验真实站点与证书即可</li></ol><p>按上述清单配置，Mac + 小米手机用 Charles 抓 APP 请求（含查看 Referer）可以稳定复现。</p>`,82)])])}const P=e(l,[["render",i]]);export{g as __pageData,P as default};
